@Override
public List<EncodingResult> detect(TikaInputStream tis, Metadata metadata, ParseContext context) throws IOException {
    Charset cs = charsetFromContentType(metadata);
    if (cs == null) {
        cs = charsetFromContentTypeHint(metadata);
    }
    if (cs == null) {
        cs = charsetFromContentEncoding(metadata);
    }
    if (cs == null) {
        return Collections.emptyList();
    }
    return List.of(new EncodingResult(cs, 1.0f, cs.name(), EncodingResult.ResultType.DECLARATIVE));
}
